CREATE OR REPLACE FUNCTION public.apply_course_import(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_role text := coalesce(auth.jwt() ->> 'role', '');
  actor_id uuid := auth.uid();
  conflicts jsonb := '[]'::jsonb;
  item jsonb;
  existing record;
  inserted_count integer := 0;
  updated_count integer := 0;
  unchanged_count integer := 0;
  imported_course_id uuid;
  statistics jsonb;
begin
  if caller_role <> 'service_role' and not private_course_editor.is_course_admin() then
    raise exception 'course import requires an active course administrator'
      using errcode = '42501';
  end if;

  if jsonb_typeof(payload) <> 'object'
    or payload ->> 'schema_version' <> '1'
    or coalesce(payload ->> 'source_label', '') = ''
    or coalesce(payload ->> 'source_hash', '') !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(payload -> 'courses') <> 'array'
    or jsonb_array_length(payload -> 'courses') <> 1
    or jsonb_typeof(payload -> 'chapters') <> 'array'
    or jsonb_typeof(payload -> 'modules') <> 'array'
    or jsonb_typeof(payload -> 'lessons') <> 'array'
    or jsonb_typeof(payload -> 'blocks') <> 'array'
    or jsonb_typeof(payload -> 'assignments') <> 'array'
    or jsonb_typeof(payload -> 'appendices') <> 'array'
  then
    raise exception 'invalid course import payload';
  end if;

  imported_course_id := ((payload -> 'courses' -> 0) ->> 'id')::uuid;

  -- Serialize imports for the same stable course slug before collision preflight.
  perform pg_advisory_xact_lock(
    hashtextextended(coalesce((payload -> 'courses' -> 0) ->> 'slug', imported_course_id::text), 0)
  );

  -- Preflight every collision before the first course-content write. Existing
  -- structural/admin edits are preserved instead of being guessed over.
  for item in select value from jsonb_array_elements(payload -> 'courses') loop
    select * into existing from public.courses where id = (item ->> 'id')::uuid;
    if found and (
      existing.slug is distinct from item ->> 'slug'
      or existing.title is distinct from item ->> 'title'
      or existing.description is distinct from item ->> 'description'
    ) then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'courses', 'id', item ->> 'id', 'reason', 'structural_mismatch'
      ));
    end if;
    select * into existing from public.courses
      where slug = item ->> 'slug' and id <> (item ->> 'id')::uuid;
    if found then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'courses', 'id', item ->> 'id', 'reason', 'stable_key_collision'
      ));
    end if;
  end loop;

  for item in select value from jsonb_array_elements(payload -> 'chapters') loop
    select * into existing from public.course_chapters where id = (item ->> 'id')::uuid;
    if found and (
      existing.course_id is distinct from (item ->> 'course_id')::uuid
      or existing.number is distinct from (item ->> 'number')::smallint
      or existing.title is distinct from item ->> 'title'
      or existing.description is distinct from item ->> 'description'
      or existing.sort_order is distinct from (item ->> 'sort_order')::integer
    ) then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'chapters', 'id', item ->> 'id', 'reason', 'structural_mismatch'
      ));
    end if;
    select * into existing from public.course_chapters
      where course_id = (item ->> 'course_id')::uuid
        and (number = (item ->> 'number')::smallint or sort_order = (item ->> 'sort_order')::integer)
        and id <> (item ->> 'id')::uuid;
    if found then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'chapters', 'id', item ->> 'id', 'reason', 'stable_key_collision'
      ));
    end if;
  end loop;

  for item in select value from jsonb_array_elements(payload -> 'modules') loop
    select * into existing from public.course_modules where id = (item ->> 'id')::uuid;
    if found and (
      existing.chapter_id is distinct from (item ->> 'chapter_id')::uuid
      or existing.source_number is distinct from (item ->> 'source_number')::smallint
      or existing.title is distinct from item ->> 'title'
      or existing.objective is distinct from item ->> 'objective'
      or existing.duration is distinct from item ->> 'duration'
      or existing.sort_order is distinct from (item ->> 'sort_order')::integer
    ) then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'modules', 'id', item ->> 'id', 'reason', 'structural_mismatch'
      ));
    end if;
    select * into existing from public.course_modules
      where chapter_id = (item ->> 'chapter_id')::uuid
        and (source_number = (item ->> 'source_number')::smallint or sort_order = (item ->> 'sort_order')::integer)
        and id <> (item ->> 'id')::uuid;
    if found then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'modules', 'id', item ->> 'id', 'reason', 'stable_key_collision'
      ));
    end if;
  end loop;

  for item in select value from jsonb_array_elements(payload -> 'lessons') loop
    select * into existing from public.course_lessons where id = (item ->> 'id')::uuid;
    if found and (
      existing.module_id is distinct from (item ->> 'module_id')::uuid
      or existing.source_heading is distinct from item ->> 'source_heading'
      or existing.title is distinct from item ->> 'title'
      or existing.summary is distinct from item ->> 'summary'
      or existing.sort_order is distinct from (item ->> 'sort_order')::integer
    ) then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'lessons', 'id', item ->> 'id', 'reason', 'structural_mismatch'
      ));
    end if;
    select * into existing from public.course_lessons
      where module_id = (item ->> 'module_id')::uuid
        and (source_heading = item ->> 'source_heading' or sort_order = (item ->> 'sort_order')::integer)
        and id <> (item ->> 'id')::uuid;
    if found then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'lessons', 'id', item ->> 'id', 'reason', 'stable_key_collision'
      ));
    end if;
  end loop;

  for item in select value from jsonb_array_elements(payload -> 'blocks') loop
    if item ->> 'origin' <> 'source' or coalesce(item ->> 'source_hash', '') !~ '^[0-9a-f]{64}$' then
      raise exception 'invalid source block in course import payload';
    end if;
    select * into existing from public.course_blocks where id = (item ->> 'id')::uuid;
    if found and existing.origin = 'admin' then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'blocks', 'id', item ->> 'id', 'reason', 'admin_origin'
      ));
    elsif found and existing.source_hash is distinct from item ->> 'source_hash' then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'blocks', 'id', item ->> 'id', 'reason', 'source_hash_mismatch'
      ));
    elsif found and (
      existing.lesson_id is distinct from (item ->> 'lesson_id')::uuid
      or existing.block_type::text is distinct from item ->> 'block_type'
      or existing.content_json is distinct from item -> 'content_json'
      or existing.source_heading is distinct from item ->> 'source_heading'
      or existing.source_start_line is distinct from (item ->> 'source_start_line')::integer
      or existing.source_end_line is distinct from (item ->> 'source_end_line')::integer
    ) then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'blocks', 'id', item ->> 'id', 'reason', 'source_hash_content_mismatch'
      ));
    end if;
    select * into existing from public.course_blocks
      where lesson_id = (item ->> 'lesson_id')::uuid
        and sort_order = (item ->> 'sort_order')::integer
        and id <> (item ->> 'id')::uuid;
    if found then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'blocks', 'id', item ->> 'id',
        'reason', case when existing.origin = 'admin' then 'admin_origin' else 'stable_key_collision' end
      ));
    end if;
  end loop;

  for item in select value from jsonb_array_elements(payload -> 'assignments') loop
    select * into existing from public.course_assignments where id = (item ->> 'id')::uuid;
    if found and (
      existing.module_id is distinct from (item ->> 'module_id')::uuid
      or existing.title is distinct from item ->> 'title'
      or existing.instructions_json is distinct from item -> 'instructions_json'
      or existing.inputs_json is distinct from item -> 'inputs_json'
      or existing.deliverables_json is distinct from item -> 'deliverables_json'
      or existing.rubric_json is distinct from item -> 'rubric_json'
      or existing.review_questions_json is distinct from item -> 'review_questions_json'
      or existing.instructor_note is distinct from nullif(item ->> 'instructor_note', '')
    ) then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'assignments', 'id', item ->> 'id', 'reason', 'structural_mismatch'
      ));
    end if;
    select * into existing from public.course_assignments
      where module_id = (item ->> 'module_id')::uuid and id <> (item ->> 'id')::uuid;
    if found then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'assignments', 'id', item ->> 'id', 'reason', 'stable_key_collision'
      ));
    end if;
  end loop;

  for item in select value from jsonb_array_elements(payload -> 'appendices') loop
    if coalesce(item ->> 'source_hash', '') !~ '^[0-9a-f]{64}$' then
      raise exception 'invalid appendix source hash in course import payload';
    end if;
    select * into existing from public.course_appendices where id = (item ->> 'id')::uuid;
    if found and existing.source_hash is distinct from item ->> 'source_hash' then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'appendices', 'id', item ->> 'id', 'reason', 'source_hash_mismatch'
      ));
    elsif found and (
      existing.course_id is distinct from (item ->> 'course_id')::uuid
      or existing.code is distinct from item ->> 'code'
      or existing.title is distinct from item ->> 'title'
      or existing.content_json is distinct from item -> 'content_json'
      or existing.source_heading is distinct from item ->> 'source_heading'
      or existing.source_start_line is distinct from (item ->> 'source_start_line')::integer
      or existing.source_end_line is distinct from (item ->> 'source_end_line')::integer
    ) then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'appendices', 'id', item ->> 'id', 'reason', 'source_hash_content_mismatch'
      ));
    end if;
    select * into existing from public.course_appendices
      where course_id = (item ->> 'course_id')::uuid
        and (code = item ->> 'code' or sort_order = (item ->> 'sort_order')::integer)
        and id <> (item ->> 'id')::uuid;
    if found then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'table', 'appendices', 'id', item ->> 'id', 'reason', 'stable_key_collision'
      ));
    end if;
  end loop;

  if jsonb_array_length(conflicts) > 0 then
    statistics := jsonb_build_object(
      'inserted', 0, 'updated', 0, 'unchanged', 0, 'conflicts', jsonb_array_length(conflicts)
    );
    insert into public.course_import_runs (
      course_id, source_path_label, source_hash, status, statistics_json, conflict_json, created_by
    ) values (
      case when exists (select 1 from public.courses where id = imported_course_id)
        then imported_course_id else null end,
      payload ->> 'source_label', payload ->> 'source_hash', 'conflict', statistics, conflicts, actor_id
    );
    return jsonb_build_object(
      'status', 'conflict', 'inserted', 0, 'updated', 0, 'unchanged', 0, 'conflicts', conflicts
    );
  end if;

  for item in select value from jsonb_array_elements(payload -> 'courses') loop
    if exists (select 1 from public.courses where id = (item ->> 'id')::uuid) then
      unchanged_count := unchanged_count + 1;
    else
      insert into public.courses (id, slug, title, description, status, version)
      values ((item ->> 'id')::uuid, item ->> 'slug', item ->> 'title', item ->> 'description',
        (item ->> 'status')::public.course_status, (item ->> 'version')::integer);
      inserted_count := inserted_count + 1;
    end if;
  end loop;

  for item in select value from jsonb_array_elements(payload -> 'chapters') loop
    if exists (select 1 from public.course_chapters where id = (item ->> 'id')::uuid) then
      unchanged_count := unchanged_count + 1;
    else
      insert into public.course_chapters (id, course_id, number, title, description, sort_order, version)
      values ((item ->> 'id')::uuid, (item ->> 'course_id')::uuid, (item ->> 'number')::smallint,
        item ->> 'title', item ->> 'description', (item ->> 'sort_order')::integer, (item ->> 'version')::integer);
      inserted_count := inserted_count + 1;
    end if;
  end loop;

  for item in select value from jsonb_array_elements(payload -> 'modules') loop
    if exists (select 1 from public.course_modules where id = (item ->> 'id')::uuid) then
      unchanged_count := unchanged_count + 1;
    else
      insert into public.course_modules (
        id, chapter_id, source_number, title, objective, duration, status, sort_order, version
      ) values (
        (item ->> 'id')::uuid, (item ->> 'chapter_id')::uuid, (item ->> 'source_number')::smallint,
        item ->> 'title', item ->> 'objective', item ->> 'duration',
        (item ->> 'status')::public.course_status, (item ->> 'sort_order')::integer,
        (item ->> 'version')::integer
      );
      inserted_count := inserted_count + 1;
    end if;
  end loop;

  for item in select value from jsonb_array_elements(payload -> 'lessons') loop
    if exists (select 1 from public.course_lessons where id = (item ->> 'id')::uuid) then
      unchanged_count := unchanged_count + 1;
    else
      insert into public.course_lessons (
        id, module_id, source_heading, title, summary, status, sort_order, version
      ) values (
        (item ->> 'id')::uuid, (item ->> 'module_id')::uuid, item ->> 'source_heading',
        item ->> 'title', item ->> 'summary', (item ->> 'status')::public.course_status,
        (item ->> 'sort_order')::integer, (item ->> 'version')::integer
      );
      inserted_count := inserted_count + 1;
    end if;
  end loop;

  for item in select value from jsonb_array_elements(payload -> 'blocks') loop
    select * into existing from public.course_blocks where id = (item ->> 'id')::uuid;
    if not found then
      insert into public.course_blocks (
        id, lesson_id, block_type, content_json, source_heading, source_start_line, source_end_line,
        source_hash, origin, needs_review, sort_order, version
      ) values (
        (item ->> 'id')::uuid, (item ->> 'lesson_id')::uuid,
        (item ->> 'block_type')::public.course_block_type, item -> 'content_json',
        item ->> 'source_heading', (item ->> 'source_start_line')::integer,
        (item ->> 'source_end_line')::integer, item ->> 'source_hash',
        (item ->> 'origin')::public.course_content_origin, (item ->> 'needs_review')::boolean,
        (item ->> 'sort_order')::integer, (item ->> 'version')::integer
      );
      inserted_count := inserted_count + 1;
    elsif existing.needs_review is distinct from (item ->> 'needs_review')::boolean
      or existing.sort_order is distinct from (item ->> 'sort_order')::integer
    then
      update public.course_blocks set
        needs_review = (item ->> 'needs_review')::boolean,
        sort_order = (item ->> 'sort_order')::integer,
        version = version + 1,
        updated_at = now()
      where id = (item ->> 'id')::uuid;
      updated_count := updated_count + 1;
    else
      unchanged_count := unchanged_count + 1;
    end if;
  end loop;

  for item in select value from jsonb_array_elements(payload -> 'assignments') loop
    if exists (select 1 from public.course_assignments where id = (item ->> 'id')::uuid) then
      unchanged_count := unchanged_count + 1;
    else
      insert into public.course_assignments (
        id, module_id, title, instructions_json, inputs_json, deliverables_json, rubric_json,
        review_questions_json, instructor_note, status, version
      ) values (
        (item ->> 'id')::uuid, (item ->> 'module_id')::uuid, item ->> 'title',
        item -> 'instructions_json', item -> 'inputs_json', item -> 'deliverables_json',
        item -> 'rubric_json', item -> 'review_questions_json', nullif(item ->> 'instructor_note', ''),
        (item ->> 'status')::public.course_status, (item ->> 'version')::integer
      );
      inserted_count := inserted_count + 1;
    end if;
  end loop;

  for item in select value from jsonb_array_elements(payload -> 'appendices') loop
    select * into existing from public.course_appendices where id = (item ->> 'id')::uuid;
    if not found then
      insert into public.course_appendices (
        id, course_id, code, title, content_json, source_heading, source_start_line, source_end_line,
        source_hash, needs_review, status, sort_order, version
      ) values (
        (item ->> 'id')::uuid, (item ->> 'course_id')::uuid, item ->> 'code', item ->> 'title',
        item -> 'content_json', item ->> 'source_heading', (item ->> 'source_start_line')::integer,
        (item ->> 'source_end_line')::integer, item ->> 'source_hash',
        (item ->> 'needs_review')::boolean, (item ->> 'status')::public.course_status,
        (item ->> 'sort_order')::integer, (item ->> 'version')::integer
      );
      inserted_count := inserted_count + 1;
    elsif existing.needs_review is distinct from (item ->> 'needs_review')::boolean
      or existing.sort_order is distinct from (item ->> 'sort_order')::integer
    then
      update public.course_appendices set
        needs_review = (item ->> 'needs_review')::boolean,
        sort_order = (item ->> 'sort_order')::integer,
        version = version + 1,
        updated_at = now()
      where id = (item ->> 'id')::uuid;
      updated_count := updated_count + 1;
    else
      unchanged_count := unchanged_count + 1;
    end if;
  end loop;

  statistics := jsonb_build_object(
    'inserted', inserted_count, 'updated', updated_count, 'unchanged', unchanged_count, 'conflicts', 0
  );
  insert into public.course_import_runs (
    course_id, source_path_label, source_hash, status, statistics_json, conflict_json, created_by
  ) values (
    imported_course_id, payload ->> 'source_label', payload ->> 'source_hash', 'succeeded',
    statistics, '[]'::jsonb, actor_id
  );

  return jsonb_build_object(
    'status', 'succeeded', 'inserted', inserted_count, 'updated', updated_count,
    'unchanged', unchanged_count, 'conflicts', '[]'::jsonb
  );
end
$function$

CREATE OR REPLACE FUNCTION public.update_course_block(p_block_id uuid, p_expected_version integer, p_content jsonb, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
  current_row public.course_blocks;
  saved_row public.course_blocks;
  owner_course_id uuid;
  previous_snapshot jsonb;
  next_snapshot jsonb;
begin
  actor_id := private_course_editor.assert_course_editor_writer(p_actor_id);
  select * into current_row
  from public.course_blocks
  where id = p_block_id
  for update;
  if not found or current_row.version <> p_expected_version then
    raise exception 'stale course entity version' using errcode = '40001';
  end if;
  select ch.course_id into owner_course_id
  from public.course_blocks b
  join public.course_lessons l on l.id = b.lesson_id
  join public.course_modules m on m.id = l.module_id
  join public.course_chapters ch on ch.id = m.chapter_id
  where b.id = p_block_id;
  if owner_course_id is null then raise exception 'course block ownership is missing'; end if;
  previous_snapshot := jsonb_build_object('content', current_row.content_json, 'version', current_row.version);
  update public.course_blocks
  set content_json = p_content, version = current_row.version + 1
  where id = p_block_id and version = p_expected_version
  returning * into saved_row;
  if not found then raise exception 'stale course entity version' using errcode = '40001'; end if;
  next_snapshot := jsonb_build_object('content', saved_row.content_json, 'version', saved_row.version);
  perform private_course_editor.append_course_revision(
    owner_course_id, 'block', p_block_id, previous_snapshot, next_snapshot, 'edit', null, actor_id
  );
  return to_jsonb(saved_row);
end
$function$

CREATE OR REPLACE FUNCTION public.update_course_note(p_note_id uuid, p_expected_version integer, p_lesson_id uuid, p_content jsonb, p_position jsonb, p_pinned boolean, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
  current_row public.course_notes;
  saved_row public.course_notes;
begin
  actor_id := private_course_editor.assert_course_editor_writer(p_actor_id);
  select * into current_row from public.course_notes where id = p_note_id for update;
  if not found or current_row.version <> p_expected_version then
    raise exception 'stale course entity version' using errcode = '40001';
  end if;
  update public.course_notes set
    lesson_id = p_lesson_id, content_json = p_content, position_json = p_position,
    pinned = p_pinned, version = current_row.version + 1
  where id = p_note_id and version = p_expected_version
  returning * into saved_row;
  if not found then raise exception 'stale course entity version' using errcode = '40001'; end if;
  perform private_course_editor.append_course_revision(
    current_row.course_id, 'note', p_note_id,
    private_course_editor.note_snapshot(current_row), private_course_editor.note_snapshot(saved_row),
    'edit', null, actor_id
  );
  return to_jsonb(saved_row);
end
$function$

CREATE OR REPLACE FUNCTION public.delete_course_note(p_note_id uuid, p_expected_version integer, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
  current_row public.course_notes;
begin
  actor_id := private_course_editor.assert_course_editor_writer(p_actor_id);
  select * into current_row from public.course_notes where id = p_note_id for update;
  if not found or current_row.version <> p_expected_version then
    raise exception 'stale course entity version' using errcode = '40001';
  end if;
  delete from public.course_notes where id = p_note_id and version = p_expected_version;
  if not found then raise exception 'stale course entity version' using errcode = '40001'; end if;
  perform private_course_editor.append_course_revision(
    current_row.course_id, 'note', p_note_id,
    private_course_editor.note_snapshot(current_row),
    private_course_editor.note_tombstone(p_note_id, current_row.course_id, current_row.version + 1),
    'delete', null, actor_id
  );
  return to_jsonb(current_row);
end
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_course_note(p_course_id uuid, p_lesson_id uuid, p_content jsonb, p_position jsonb, p_pinned boolean, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
  note_id uuid := gen_random_uuid();
  saved_row public.course_notes;
begin
  actor_id := private_course_editor.assert_course_editor_writer(p_actor_id);
  if actor_id is null then raise exception 'course note actor is required' using errcode = '42501'; end if;
  insert into public.course_notes (
    id, course_id, lesson_id, author_id, content_json, position_json, pinned, version
  ) values (note_id, p_course_id, p_lesson_id, actor_id, p_content, p_position, p_pinned, 1)
  returning * into saved_row;
  perform private_course_editor.append_course_revision(
    p_course_id, 'note', note_id,
    private_course_editor.note_tombstone(note_id, p_course_id, 0),
    private_course_editor.note_snapshot(saved_row), 'create', null, actor_id
  );
  return to_jsonb(saved_row);
end
$function$

CREATE OR REPLACE FUNCTION public.update_course_entity(p_entity_kind text, p_entity_id uuid, p_expected_version integer, p_patch jsonb, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
  previous_snapshot jsonb;
  next_snapshot jsonb;
  candidate jsonb;
  owner_course_id uuid;
  revision_type public.course_revision_entity_type;
  unexpected_keys text[];
begin
  actor_id := private_course_editor.assert_course_editor_writer(p_actor_id);
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' or p_patch = '{}'::jsonb then
    raise exception 'course entity patch must be a non-empty object' using errcode = '22023';
  end if;
  select array_agg(key) into unexpected_keys
  from jsonb_object_keys(p_patch) key
  where not (
    (p_entity_kind in ('course', 'chapter') and key in ('title', 'description')) or
    (p_entity_kind = 'module' and key in ('title', 'objective', 'duration', 'status')) or
    (p_entity_kind = 'lesson' and key in ('title', 'summary', 'status')) or
    (p_entity_kind = 'assignment' and key in ('title', 'instructions', 'inputs', 'deliverables', 'rubric', 'reviewQuestions', 'instructorNote', 'status')) or
    (p_entity_kind = 'appendix' and key in ('title', 'content', 'status'))
  );
  if unexpected_keys is not null then raise exception 'unsupported course entity patch fields: %', unexpected_keys using errcode = '22023'; end if;

  previous_snapshot := private_course_editor.course_entity_snapshot(p_entity_kind, p_entity_id);
  if (previous_snapshot ->> 'version')::integer <> p_expected_version then
    raise exception 'stale course entity version' using errcode = '40001';
  end if;
  candidate := previous_snapshot || p_patch;
  if candidate ? 'title' and btrim(coalesce(candidate ->> 'title', '')) = '' then
    raise exception 'course entity title cannot be empty' using errcode = '22023';
  end if;
  if p_entity_kind = 'assignment' then
    if candidate -> 'instructions' is null or candidate -> 'inputs' is null or candidate -> 'deliverables' is null
      or candidate -> 'rubric' is null or candidate -> 'reviewQuestions' is null then
      raise exception 'assignment sections cannot be null' using errcode = '22023';
    end if;
  elsif p_entity_kind = 'appendix' and candidate -> 'content' is null then
    raise exception 'appendix content cannot be null' using errcode = '22023';
  end if;

  next_snapshot := private_course_editor.restore_course_entity(p_entity_kind, p_entity_id, p_expected_version, candidate);
  owner_course_id := (next_snapshot ->> 'courseId')::uuid;
  revision_type := case p_entity_kind
    when 'module' then 'module'::public.course_revision_entity_type
    when 'lesson' then 'lesson'::public.course_revision_entity_type
    when 'assignment' then 'assignment'::public.course_revision_entity_type
    else 'course'::public.course_revision_entity_type
  end;
  perform private_course_editor.append_course_revision(
    owner_course_id, revision_type, p_entity_id, previous_snapshot, next_snapshot, 'edit', null, actor_id
  );
  return jsonb_build_object('kind', p_entity_kind, 'entity', next_snapshot);
end
$function$

