CREATE OR REPLACE FUNCTION public.create_course_image_block(p_lesson_id uuid, p_asset_id uuid, p_alt_text text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
  owner_course_id uuid;
  asset_row public.course_assets;
  saved_block public.course_blocks;
  next_sort integer;
  before_snapshot jsonb;
  after_snapshot jsonb;
begin
  actor_id := private_course_editor.assert_course_editor_writer(p_actor_id);
  select ch.course_id into owner_course_id
  from public.course_lessons l
  join public.course_modules m on m.id = l.module_id
  join public.course_chapters ch on ch.id = m.chapter_id
  where l.id = p_lesson_id for update of l;
  if owner_course_id is null then raise exception 'course lesson not found' using errcode = 'P0002'; end if;
  select * into asset_row from public.course_assets where id = p_asset_id for update;
  if not found or asset_row.course_id is distinct from owner_course_id or asset_row.uploaded_by is distinct from actor_id or asset_row.block_id is not null then
    raise exception 'course asset cannot be attached to this lesson' using errcode = '42501';
  end if;
  select coalesce(max(sort_order), -1) + 1 into next_sort from public.course_blocks where lesson_id = p_lesson_id;
  insert into public.course_blocks (
    lesson_id, block_type, content_json, origin, needs_review, sort_order, version
  ) values (
    p_lesson_id, 'image', jsonb_build_object('assetId', p_asset_id, 'altText', p_alt_text),
    'admin', false, next_sort, 1
  ) returning * into saved_block;
  update public.course_assets set block_id = saved_block.id where id = p_asset_id;
  before_snapshot := private_course_editor.course_image_block_tombstone(saved_block.id, owner_course_id, p_lesson_id, 0);
  after_snapshot := private_course_editor.course_image_block_snapshot(saved_block, owner_course_id);
  perform private_course_editor.append_course_revision(
    owner_course_id, 'block', saved_block.id, before_snapshot, after_snapshot, 'create', null, actor_id
  );
  return to_jsonb(saved_block);
end
$function$

