CREATE OR REPLACE FUNCTION private_course_editor.enforce_version_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.version::bigint <> old.version::bigint + 1 then
    raise exception 'stale course entity version: expected %, received %', old.version + 1, new.version
      using errcode = '40001';
  end if;
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private_course_editor.apply_course_entity_revision(p_revision_id uuid, p_direction text, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
  selected public.course_revisions;
  latest public.course_revisions;
  p_kind text;
  current_snapshot jsonb;
  target_snapshot jsonb;
  applied_snapshot jsonb;
begin
  actor_id := private_course_editor.assert_course_editor_writer(p_actor_id);
  select * into selected from public.course_revisions where id = p_revision_id for update;
  if not found then raise exception 'course revision not found'; end if;
  p_kind := selected.next_value ->> 'kind';
  if p_kind not in ('course', 'chapter', 'module', 'lesson', 'assignment', 'appendix') then
    raise exception 'revision is not a structured course entity' using errcode = '22023';
  end if;
  select * into latest from public.course_revisions
  where entity_type = selected.entity_type and entity_id = selected.entity_id
  order by sequence desc limit 1 for update;
  if latest.id is distinct from selected.id then raise exception 'revision is not the latest entity revision' using errcode = '40001'; end if;
  if p_direction = 'undo' and selected.action not in ('edit', 'redo') then
    raise exception 'revision cannot be undone' using errcode = '40001';
  elsif p_direction = 'redo' and selected.action <> 'undo' then
    raise exception 'redo requires latest undo revision' using errcode = '40001';
  elsif p_direction not in ('undo', 'redo') then
    raise exception 'invalid revision direction';
  end if;
  current_snapshot := private_course_editor.course_entity_snapshot(p_kind, selected.entity_id);
  if current_snapshot is distinct from selected.next_value then
    raise exception 'current snapshot does not match revision head' using errcode = '40001';
  end if;
  target_snapshot := selected.previous_value;
  applied_snapshot := private_course_editor.restore_course_entity(
    p_kind, selected.entity_id, (current_snapshot ->> 'version')::integer, target_snapshot
  );
  perform private_course_editor.append_course_revision(
    selected.course_id, selected.entity_type, selected.entity_id, current_snapshot, applied_snapshot,
    p_direction, selected.id, actor_id
  );
  return jsonb_build_object('entity_type', selected.entity_type, 'kind', p_kind, 'entity', applied_snapshot);
end
$function$

CREATE OR REPLACE FUNCTION private_course_editor.apply_course_block_or_note_revision(p_revision_id uuid, p_direction text, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
  selected public.course_revisions;
  latest public.course_revisions;
  block_row public.course_blocks;
  saved_block public.course_blocks;
  note_row public.course_notes;
  saved_note public.course_notes;
  owner_course_id uuid;
  current_snapshot jsonb;
  target_snapshot jsonb;
  applied_snapshot jsonb;
  current_version integer;
  next_version integer;
begin
  actor_id := private_course_editor.assert_course_editor_writer(p_actor_id);
  select * into selected from public.course_revisions where id = p_revision_id for update;
  if not found then raise exception 'course revision not found'; end if;
  select * into latest from public.course_revisions
  where entity_type = selected.entity_type and entity_id = selected.entity_id
  order by sequence desc limit 1 for update;
  if latest.id is distinct from selected.id then
    raise exception 'revision is not the latest entity revision' using errcode = '40001';
  end if;
  if p_direction = 'undo' and selected.action not in ('edit', 'create', 'delete', 'redo') then
    raise exception 'revision cannot be undone' using errcode = '40001';
  elsif p_direction = 'redo' and selected.action <> 'undo' then
    raise exception 'redo requires latest undo revision' using errcode = '40001';
  elsif p_direction not in ('undo', 'redo') then
    raise exception 'invalid revision direction';
  end if;
  target_snapshot := selected.previous_value;

  if selected.entity_type = 'block' then
    if (selected.next_value ->> 'version')::integer <> (selected.previous_value ->> 'version')::integer + 1 then
      raise exception 'invalid revision version chain' using errcode = '40001';
    end if;
    select * into block_row
    from public.course_blocks
    where id = selected.entity_id
    for update;
    if not found then raise exception 'revision entity ownership mismatch' using errcode = '40001'; end if;
    select ch.course_id into owner_course_id
    from public.course_blocks b
    join public.course_lessons l on l.id = b.lesson_id
    join public.course_modules m on m.id = l.module_id
    join public.course_chapters ch on ch.id = m.chapter_id
    where b.id = selected.entity_id;
    if owner_course_id is distinct from selected.course_id then raise exception 'revision entity ownership mismatch' using errcode = '40001'; end if;
    current_snapshot := jsonb_build_object('content', block_row.content_json, 'version', block_row.version);
    if current_snapshot is distinct from selected.next_value then
      raise exception 'current snapshot does not match revision head' using errcode = '40001';
    end if;
    next_version := block_row.version + 1;
    update public.course_blocks set content_json = target_snapshot -> 'content', version = next_version
    where id = block_row.id and version = block_row.version returning * into saved_block;
    if not found then raise exception 'stale course entity version' using errcode = '40001'; end if;
    applied_snapshot := jsonb_build_object('content', saved_block.content_json, 'version', saved_block.version);
    perform private_course_editor.append_course_revision(
      selected.course_id, 'block', selected.entity_id, current_snapshot, applied_snapshot,
      p_direction, selected.id, actor_id
    );
    return jsonb_build_object('entity_type', 'block', 'entity', to_jsonb(saved_block));
  elsif selected.entity_type = 'note' then
    if (selected.next_value ->> 'version')::integer <> (selected.previous_value ->> 'version')::integer + 1
      or selected.next_value ->> 'id' <> selected.entity_id::text
      or selected.previous_value ->> 'id' <> selected.entity_id::text
      or selected.next_value ->> 'courseId' <> selected.course_id::text
      or selected.previous_value ->> 'courseId' <> selected.course_id::text
    then raise exception 'invalid note revision chain' using errcode = '40001'; end if;
    if selected.action = 'create' and (
      coalesce((selected.previous_value ->> 'deleted')::boolean, false) is not true
      or coalesce((selected.next_value ->> 'deleted')::boolean, false) is true
    ) then raise exception 'invalid note create revision' using errcode = '40001';
    elsif selected.action = 'delete' and (
      coalesce((selected.previous_value ->> 'deleted')::boolean, false) is true
      or coalesce((selected.next_value ->> 'deleted')::boolean, false) is not true
    ) then raise exception 'invalid note delete revision' using errcode = '40001';
    elsif selected.action = 'edit' and (
      coalesce((selected.previous_value ->> 'deleted')::boolean, false) is true
      or coalesce((selected.next_value ->> 'deleted')::boolean, false) is true
    ) then raise exception 'invalid note edit revision' using errcode = '40001';
    end if;
    select * into note_row from public.course_notes where id = selected.entity_id for update;
    if found then
      current_snapshot := private_course_editor.note_snapshot(note_row);
    else
      current_snapshot := selected.next_value;
      if coalesce((current_snapshot ->> 'deleted')::boolean, false) is not true then
        raise exception 'current snapshot does not match revision head' using errcode = '40001';
      end if;
    end if;
    if current_snapshot is distinct from selected.next_value then
      raise exception 'current snapshot does not match revision head' using errcode = '40001';
    end if;
    current_version := (current_snapshot ->> 'version')::integer;
    next_version := current_version + 1;
    if coalesce((target_snapshot ->> 'deleted')::boolean, false) then
      if note_row.id is null then raise exception 'note already deleted' using errcode = '40001'; end if;
      delete from public.course_notes where id = selected.entity_id and version = current_version;
      if not found then raise exception 'stale course entity version' using errcode = '40001'; end if;
      applied_snapshot := private_course_editor.note_tombstone(selected.entity_id, selected.course_id, next_version);
      saved_note := null;
    else
      if target_snapshot ->> 'courseId' <> selected.course_id::text
        or target_snapshot ->> 'id' <> selected.entity_id::text then
        raise exception 'revision entity ownership mismatch' using errcode = '40001';
      end if;
      if note_row.id is null then
        insert into public.course_notes (
          id, course_id, lesson_id, author_id, content_json, position_json, pinned, version
        ) values (
          selected.entity_id, selected.course_id, nullif(target_snapshot ->> 'lessonId', '')::uuid,
          (target_snapshot ->> 'authorId')::uuid, target_snapshot -> 'content', target_snapshot -> 'position',
          (target_snapshot ->> 'pinned')::boolean, next_version
        ) returning * into saved_note;
      else
        update public.course_notes set
          lesson_id = nullif(target_snapshot ->> 'lessonId', '')::uuid,
          content_json = target_snapshot -> 'content', position_json = target_snapshot -> 'position',
          pinned = (target_snapshot ->> 'pinned')::boolean, version = next_version
        where id = selected.entity_id and version = current_version returning * into saved_note;
        if not found then raise exception 'stale course entity version' using errcode = '40001'; end if;
      end if;
      applied_snapshot := private_course_editor.note_snapshot(saved_note);
    end if;
    perform private_course_editor.append_course_revision(
      selected.course_id, 'note', selected.entity_id, current_snapshot, applied_snapshot,
      p_direction, selected.id, actor_id
    );
    return jsonb_build_object('entity_type', 'note', 'entity', case when saved_note.id is null then null else to_jsonb(saved_note) end);
  end if;
  raise exception 'unsupported revision entity type';
end
$function$

CREATE OR REPLACE FUNCTION private_course_editor.assert_course_editor_writer(p_actor_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_role text := coalesce(auth.jwt() ->> 'role', '');
  authenticated_id uuid := auth.uid();
begin
  if caller_role = 'service_role' then
    if p_actor_id is null then
      raise exception 'service role course actor is required' using errcode = '42501';
    end if;
    if not exists (
      select 1 from public.profiles
      where id = p_actor_id
        and role = 'admin'::public.profile_role
        and status = 'active'::public.profile_status
    ) then
      raise exception 'service role course actor must be an active admin' using errcode = '42501';
    end if;
    return p_actor_id;
  end if;
  if caller_role = 'authenticated' and p_actor_id is not null and p_actor_id is distinct from authenticated_id then
    raise exception 'authenticated course actor spoofing is forbidden' using errcode = '42501';
  end if;
  if caller_role <> 'authenticated' or authenticated_id is null or not private_course_editor.is_course_admin() then
    raise exception 'course editing requires an active course administrator'
      using errcode = '42501';
  end if;
  return authenticated_id;
end
$function$

CREATE OR REPLACE FUNCTION private_course_editor.apply_course_image_block_revision(p_revision_id uuid, p_direction text, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
  selected public.course_revisions;
  latest public.course_revisions;
  block_row public.course_blocks;
  saved_block public.course_blocks;
  current_snapshot jsonb;
  target_snapshot jsonb;
  applied_snapshot jsonb;
  next_version integer;
  asset_id uuid;
begin
  actor_id := private_course_editor.assert_course_editor_writer(p_actor_id);
  select * into selected from public.course_revisions where id = p_revision_id for update;
  if not found or selected.next_value ->> 'kind' <> 'imageBlock' then raise exception 'image block revision not found'; end if;
  select * into latest from public.course_revisions where entity_type='block' and entity_id=selected.entity_id order by sequence desc limit 1 for update;
  if latest.id is distinct from selected.id then raise exception 'revision is not the latest entity revision' using errcode='40001'; end if;
  if p_direction='undo' and selected.action not in ('create','redo') then raise exception 'revision cannot be undone' using errcode='40001';
  elsif p_direction='redo' and selected.action <> 'undo' then raise exception 'redo requires latest undo revision' using errcode='40001';
  elsif p_direction not in ('undo','redo') then raise exception 'invalid revision direction'; end if;
  select * into block_row from public.course_blocks where id=selected.entity_id for update;
  if found then current_snapshot := private_course_editor.course_image_block_snapshot(block_row, selected.course_id);
  else current_snapshot := selected.next_value; end if;
  if current_snapshot is distinct from selected.next_value then raise exception 'current snapshot does not match revision head' using errcode='40001'; end if;
  target_snapshot := selected.previous_value;
  next_version := (current_snapshot ->> 'version')::integer + 1;
  if coalesce((target_snapshot ->> 'deleted')::boolean,false) then
    if block_row.id is null then raise exception 'image block already deleted' using errcode='40001'; end if;
    update public.course_assets set block_id=null where block_id=block_row.id;
    delete from public.course_blocks where id=block_row.id and version=block_row.version;
    if not found then raise exception 'stale course entity version' using errcode='40001'; end if;
    applied_snapshot := private_course_editor.course_image_block_tombstone(
      selected.entity_id, selected.course_id, (current_snapshot ->> 'lessonId')::uuid, next_version
    );
    saved_block := null;
  else
    asset_id := (target_snapshot #>> '{content,assetId}')::uuid;
    insert into public.course_blocks(id,lesson_id,block_type,content_json,origin,needs_review,sort_order,version)
      values(selected.entity_id,(target_snapshot->>'lessonId')::uuid,'image',target_snapshot->'content','admin',false,(target_snapshot->>'sortOrder')::integer,next_version)
      returning * into saved_block;
    update public.course_assets set block_id=saved_block.id where id=asset_id and course_id=selected.course_id and block_id is null;
    if not found then raise exception 'course asset cannot be reattached' using errcode='40001'; end if;
    applied_snapshot := private_course_editor.course_image_block_snapshot(saved_block, selected.course_id);
  end if;
  perform private_course_editor.append_course_revision(selected.course_id,'block',selected.entity_id,current_snapshot,applied_snapshot,p_direction,selected.id,actor_id);
  return jsonb_build_object('entity_type','block','kind','imageBlock','entity',case when saved_block.id is null then null else to_jsonb(saved_block) end);
end
$function$

CREATE OR REPLACE FUNCTION private_course_editor.apply_course_revision(p_revision_id uuid, p_direction text, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  revision_kind text;
begin
  select next_value ->> 'kind' into revision_kind from public.course_revisions where id = p_revision_id;
  if revision_kind = 'imageBlock' then
    return private_course_editor.apply_course_image_block_revision(p_revision_id, p_direction, p_actor_id);
  elsif revision_kind in ('course', 'chapter', 'module', 'lesson', 'assignment', 'appendix') then
    return private_course_editor.apply_course_entity_revision(p_revision_id, p_direction, p_actor_id);
  end if;
  return private_course_editor.apply_course_block_or_note_revision(p_revision_id, p_direction, p_actor_id);
end
$function$
